const deal = $input.first().json.result || {};
const prev = $('06_Route_Session_Status').first().json || {};

const ufDesc = deal.UF_CRM_1729774515200;
let summary = deal.UF_CRM_TI_SHORT_SUBJECT || '';
if (Array.isArray(ufDesc)) {
  summary = ufDesc.join('\n');
} else if (typeof ufDesc === 'string') {
  summary = ufDesc;
}

return [{
  json: {
    deal_id: Number(deal.ID),
    dialog_id: prev.dialog_id,
    chat_id: prev.chat_id,
    message_id: prev.message_id,
    requester_user_id: prev.requester_user_id || Number(deal.CREATED_BY_ID) || 32598,
    requester_name: prev.requester_name || ({32598: 'Eduardo Alaminos', 7: 'Élton Caetano', 352678: 'Igor Bonini'}[Number(deal.CREATED_BY_ID)] || 'Colaborador'),
    deal_title: deal.TITLE || `Chamado #${deal.ID}`,
    deal_summary: summary || deal.TITLE || 'Chamado de TI',
    user_message: prev.message_text
  }
}];

const prev = $('PostRes_02_Prepare_Prompt').first().json || {};
const llmText = $input.first().json.text || '';
let parsed = {
  intent: 'CARONA',
  reply_message: `Oi, ${prev.requester_name}! Como este chamado já foi concluído, peço que você abra um novo chamado no Bitrix24 para esse novo assunto. Assim a equipe de TI atende com a prioridade correta! 🙌`
};

const match = llmText.match(/\{[\s\S]*\}/);
if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch (e) {}
}

const intent = parsed.intent || 'CARONA';
const reply_message = parsed.reply_message || '';
const user_msg = String(prev.user_message || '').trim();

// Verificação determinística adicional de CSAT (ex: usuário digitou só "5" ou "10")
let csatRating = parsed.csat_rating ? Number(parsed.csat_rating) : null;
if (!csatRating) {
  if (/^[1-5]$/.test(user_msg)) {
    csatRating = parseInt(user_msg, 10);
  } else if (/^10$/.test(user_msg) || user_msg.includes('10/10')) {
    csatRating = 5;
  } else if (user_msg.includes('⭐') || user_msg.includes('estrela')) {
    const starCount = (user_msg.match(/⭐/g) || []).length;
    csatRating = starCount >= 1 ? Math.min(starCount, 5) : 5;
  }
}
if (csatRating) {
  csatRating = Math.max(1, Math.min(5, csatRating));
}
const isCsat = intent === 'CSAT_FEEDBACK' || csatRating !== null;
const csatComment = parsed.csat_comment || user_msg;

let timeline_comment = '';
if (intent === 'REOPEN') {
  timeline_comment = `🔄 **Chamado Reaberto pelo Solicitante**\n\nO colaborador informou que o problema persiste:\n> "${user_msg}"\n\n*Retornado para "Em atendimento" (C160:PREPARATION) para atuação da equipe técnica.*`;
} else if (intent === 'CARONA') {
  timeline_comment = `🛑 **Tentativa de Chamado Carona Bloqueada**\n\nO colaborador tentou relatar um novo assunto neste chamado concluído:\n> "${user_msg}"\n\n*O robô orientou educadamente a abertura de um novo chamado no Bitrix24.*`;
}

return [{
  json: {
    deal_id: prev.deal_id,
    dialog_id: prev.dialog_id,
    chat_id: prev.chat_id,
    message_id: prev.message_id,
    requester_user_id: prev.requester_user_id,
    requester_name: prev.requester_name,
    deal_title: prev.deal_title,
    user_message: user_msg,
    intent: isCsat ? 'CSAT_FEEDBACK' : intent,
    is_csat: isCsat,
    csat_rating: csatRating || 5,
    csat_comment: csatComment,
    reason: parsed.reason || '',
    reply_message: reply_message,
    timeline_comment: timeline_comment
  }
}];

// AVALIADOR DE DUPLICIDADE EM TEMPO REAL
const gateItems = $('01_Strict_Gate_Cat160_Pilot').all();
const fetchItems = $input.all();
const results = [];

function cleanText(t) {
  return String(t || '')
    .replace(/\[.*?\]|\(.*?\)/g, ' ')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const IT_ENTITIES = ['monitor', 'teclado', 'mouse', 'impressora', 'internet', 'rede', 'wifi', 'whatsapp', 'wpp', 'fale facil', 'atpv', 'renave', 'chassi', 'headset', 'fone', 'microwork', 'cloud', 'outlook', 'email'];

function extractChassi(t) {
  const m = String(t || '').match(/\b(9c2[a-z0-9]{14}|[a-z0-9]{17})\b/i);
  return m ? m[1].toUpperCase() : null;
}

function checkDuplicate(newTitle, newDesc, oldTitle, oldDesc) {
  const newFull = newTitle + ' ' + newDesc;
  const oldFull = oldTitle + ' ' + oldDesc;

  // 1. Chassi
  const c1 = extractChassi(newFull);
  const c2 = extractChassi(oldFull);
  if (c1 && c2 && c1 === c2) return { isDup: true, reason: 'Mesmo Chassi identificado: ' + c1 };

  // 2. Title inclusion
  const ct1 = cleanText(newTitle);
  const ct2 = cleanText(oldTitle);
  if (ct1.length >= 8 && ct2.length >= 8 && (ct2.includes(ct1) || ct1.includes(ct2))) {
    return { isDup: true, reason: 'Assunto idêntico ou contido: ' + ct1 };
  }

  // 3. Shared IT entity
  for (const ent of IT_ENTITIES) {
    if (ct1.includes(ent) && ct2.includes(ent)) {
      return { isDup: true, reason: 'Mesmo equipamento ou sistema já em aberto: ' + ent.toUpperCase() };
    }
  }

  return { isDup: false, reason: '' };
}

for (let i = 0; i < gateItems.length; i++) {
  const currentDeal = gateItems[i].json;
  const rawOpen = fetchItems[i]?.json?.result || [];
  const openDeals = Array.isArray(rawOpen) ? rawOpen : [rawOpen];

  let duplicateMatch = null;

  for (const oldDeal of openDeals) {
    if (!oldDeal || !oldDeal.ID) continue;

    // Apenas chamados criados nas últimas 168 horas (7 dias)
    const createdDate = new Date(oldDeal.DATE_CREATE);
    const now = new Date();
    const diffHours = (now - createdDate) / (1000 * 60 * 60);
    if (diffHours > 168) continue;

    const oldTitle = String(oldDeal.TITLE || '');
    const rawOldDesc = oldDeal.UF_CRM_1729774515200;
    const oldDesc = (Array.isArray(rawOldDesc) ? rawOldDesc.join(' ') : String(rawOldDesc || '')).trim();

    const check = checkDuplicate(currentDeal.title, currentDeal.description, oldTitle, oldDesc);

    if (check.isDup) {
      duplicateMatch = {
        original_deal_id: Number(oldDeal.ID),
        original_deal_title: oldTitle,
        duplicate_reason: check.reason
      };
      break;
    }
  }

  if (duplicateMatch) {
    results.push({
      json: {
