// Extrai ID do Deal de webhook ONCRMDEALADD ou lista do polling
const items = $input.all();
const ids = [];

for (const item of items) {
  const json = item.json;
  const body = json.body || json;

  // Polling: array em json.result
  if (json.result && Array.isArray(json.result)) {
    for (const d of json.result) {
      if (d.ID) ids.push(Number(d.ID));
    }
  }
  // Webhook ONCRMDEALADD (URL encoded ou JSON)
  else {
    let dId = null;
    if (body['data[FIELDS][ID]']) dId = Number(body['data[FIELDS][ID]']);
    else if (body.data?.FIELDS?.ID) dId = Number(body.data.FIELDS.ID);
    else if (body.FIELDS?.ID) dId = Number(body.FIELDS.ID);
    else if (body.id || body.ID) dId = Number(body.id || body.ID);
    if (dId) ids.push(dId);
