// Preserva deal context via all(), associando item a item
const reserveItems = $('02_Reserve_Deal_Session_Atomic').all();
const items = $input.all();
return items.map((item, idx) => {
  const chatId = Number(item.json.result || 0);
  const r = reserveItems[idx]?.json || {};
  return {
    json: {
      deal_id: r.deal_id,
      deal_title: r.deal_title || `Chamado #${r.deal_id}`,
      is_purchase: Boolean(r.is_purchase),
      chat_id: chatId,
      dialog_id: `chat${chatId}`
    }
  };
});

// Classificação e filtragem multi-item com suporte a Anti-Carona e Imagens (Sprint 2 Vision)
const sessions = $('04_Get_Active_Sessions_Postgres').all();
const items = $input.all();
const outputItems = [];

for (let i = 0; i < items.length; i++) {
  const session = sessions[i]?.json || {};
  const res = items[i].json.result || {};
  const messages = res.messages || [];
  const rawFiles = res.files || [];
  const filesList = Array.isArray(rawFiles) ? rawFiles : Object.values(rawFiles || {});

  const lastProcessedId = Number(session.last_processed_message_id || 0);
  const requesterId = Number(session.requester_user_id);
  const BOT_ID = 61622;
  const isCompleted = session.status === 'COMPLETED';

  // Ordena cronologicamente crescente
  messages.sort((a, b) => Number(a.id) - Number(b.id));

  const newMessages = [];
  let humanTakeoverDetected = false;
  let lastMsgId = lastProcessedId;
  let attachedImage = null;

  for (const msg of messages) {
    const msgId = Number(msg.id);
    if (msgId <= lastProcessedId) continue;
    lastMsgId = Math.max(lastMsgId, msgId);

    const authorId = Number(msg.author_id);
    // Ignora mensagens do bot (61622) ou de sistema (0)
    if (authorId === BOT_ID || authorId === 0) continue;

    // Se autor não for o solicitante nem o bot
    if (authorId !== requesterId) {
      if (!isCompleted) {
        humanTakeoverDetected = true;
        break;
      }
      continue;
    }

    // Mensagem válida do solicitante
    const cleanText = String(msg.text || '').trim();
    if (cleanText) {
      newMessages.push(cleanText);
    }

    // Checagem de anexo de imagem na mensagem (suporta array ou ID único)
    let fileIds = [];
    if (Array.isArray(msg.params?.FILE_ID)) {
      fileIds = msg.params.FILE_ID;
    } else if (msg.params?.FILE_ID) {
      fileIds = [msg.params.FILE_ID];
    }

    if (fileIds.length > 0 && filesList.length > 0) {
      for (const fid of fileIds) {
        const found = filesList.find(f => 
          Number(f.id) === Number(fid) && 
          (f.type === 'image' || ['png', 'jpg', 'jpeg', 'webp', 'bmp'].includes(String(f.extension || '').toLowerCase()))
        );
        if (found) {
          attachedImage = {
            file_id: Number(found.id),
            name: found.name || 'print_anexo.png',
            extension: found.extension || 'png'
          };
          break;
        }
      }
    }
  }

  if (humanTakeoverDetected) {
    outputItems.push({
      json: {
        deal_id: session.deal_id,
        dialog_id: session.dialog_id,
        human_takeover: true,
        last_msg_id: lastMsgId
      }
    });
    continue;
  }

  // Se AI está pausada manualmente em ticket ativo, ignora
  if (!isCompleted && session.ai_state === 'AI_PAUSED') {
    continue;
  }

  // Se há imagem ou mensagens novas
  if (newMessages.length > 0 || attachedImage) {
    const fallbackText = attachedImage ? 'O colaborador enviou um print/imagem de erro em anexo.' : '';
    outputItems.push({
      json: {
        deal_id: session.deal_id,
        chat_id: session.internal_chat_id,
        dialog_id: session.dialog_id,
        requester_user_id: requesterId,
        requester_name: session.requester_name || 'Colaborador',
        message_id: lastMsgId,
        message_text: newMessages.join('\n') || fallbackText,
        redis_memory_key: `bitrix:ti:deal:${session.deal_id}:memory`,
        ai_state: session.ai_state,
        session_status: session.status || 'ACTIVE',
        session_state: session.state || 'INIT',
        collected_data_json: session.collected_data_json || {},
        has_image: Boolean(attachedImage),
        image_file_id: attachedImage ? attachedImage.file_id : null,
        image_name: attachedImage ? attachedImage.name : null,
        image_extension: attachedImage ? attachedImage.extension : null
      }
    });
  }
}

return outputItems;

// Prepara input isolado para o Agente LangChain por Deal com contexto do card, separação Gestor vs Beneficiário e Anti-Redundância
const items = $input.all();
return items.map(item => {
  const collected = item.json.collected_data_json || {};
  const title = String(collected.deal_title || '').trim();
  const userInput = String(item.json.message_text || '').trim();
  const requesterName = String(item.json.requester_name || 'Colaborador').trim();
  const requesterPosition = String(collected.requester_position || '').trim();

  // 1. Pré-Extração Determinística de Entidades Conhecidas no Card (Anti-Redundância)
  const fullSearchText = `${title} ${userInput}`;
  const extractedEntities = [];

  // Chassi de 17 dígitos
  const chassiMatch = fullSearchText.match(/\b(9C2[A-HJ-NPR-Z0-9]{14})\b/i);
  if (chassiMatch) {
    extractedEntities.push(`Chassi Identificado: "${chassiMatch[1].toUpperCase()}" -> (REGRA ESTRITA: PROIBIDO PERGUNTAR O CHASSI NOVAMENTE AO USUÁRIO)`);
  }

  // Link de Card Bitrix
  const cardLinkMatch = fullSearchText.match(/(https:\/\/b24-[a-z0-9]+\.bitrix24\.com\.br\/crm\/deal\/details\/\d+\/)/i);
  if (cardLinkMatch) {
    extractedEntities.push(`Link do Card no Bitrix: "${cardLinkMatch[1]}" -> (REGRA ESTRITA: PROIBIDO PEDIR O LINK DO CARD NOVAMENTE)`);
  }

  // Número de Nota Fiscal
  const nfMatch = fullSearchText.match(/\b(?:nf|nota|nfe)\s*[:#ºn]?\s*(\d{4,9})\b/i);
  if (nfMatch) {
    extractedEntities.push(`Número de Nota Fiscal: "${nfMatch[1]}"`);
  }

  // Ordem de Serviço (OS)
  const osMatch = fullSearchText.match(/\b(?:os|o\.s\.)\s*[:#ºn]?\s*(\d{4,8})\b/i);
  if (osMatch) {
    extractedEntities.push(`Número da OS: "${osMatch[1]}"`);
  }

  let factsBlock = '';
  if (extractedEntities.length > 0) {
    factsBlock = `[DADOS JÁ CONFIRMADOS E COMPROVADOS NO CARD (NÃO PERGUNTE NOVAMENTE AO USUÁRIO)]:\n` +
      extractedEntities.map(e => `• ${e}`).join('\n') + '\n\n';
  }

  // 2. Detecção de solicitação em nome de terceiro (Gestor abrindo para colaborador)
  let thirdPartyNote = '';
  const thirdPartyMatch = title.match(/\b(?:para|do|da|mecanico|mecânico|vendedor|estoquista|novo colaborador|novo consultor)\b\s+([A-ZÀ-ÿ][a-zà-ÿ]+(?:\s+[A-ZÀ-ÿ][a-zà-ÿ]+)?)/i);

  if (thirdPartyMatch && thirdPartyMatch[1] && !thirdPartyMatch[1].toLowerCase().includes(requesterName.toLowerCase())) {
    const beneficiary = thirdPartyMatch[1].trim();
    thirdPartyNote = `[ATENÇÃO - CHAMADO ABERTO EM NOME DE OUTRA PESSOA]:\n` +
      `- O usuário conversando com você no chat é o(a) solicitante: ${requesterName}${requesterPosition ? ' (' + requesterPosition + ')' : ''}.\n` +
      `- O colaborador citado que precisa da liberação/suporte é: "${beneficiary}".\n` +
      `- DIRETIVA: Dirija-se sempre a ${requesterName} pelo nome dele(a). NUNCA o confunda com ${beneficiary}. Trate a demanda como uma solicitação feita por ${requesterName} em favor de ${beneficiary}.\n\n`;
  }

  let contextHeader = `[SOLICITANTE DO CARD / USUÁRIO NO CHAT]: ${requesterName}${requesterPosition ? ' (' + requesterPosition + ')' : ''}\n`;
  if (title && !title.startsWith('Chamado #') && !title.startsWith('#')) {
    contextHeader += `[TÍTULO DO CHAMADO]: "${title}"\n`;
  }

  const contextualInput = `${contextHeader}${factsBlock}${thirdPartyNote}[MENSAGEM DO COLABORADOR NO CHAT]:\n${userInput}`;

  return {
    json: {
      deal_id: item.json.deal_id,
      chat_id: item.json.chat_id,
      dialog_id: item.json.dialog_id,
      requester_user_id: item.json.requester_user_id,
      requester_name: requesterName,
      requester_position: requesterPosition,
      message_id: item.json.message_id,
      full_user_input: contextualInput,
      redis_memory_key: item.json.redis_memory_key,
      ai_state: item.json.ai_state,
      collected_data_json: collected
    }
  };
});

// Formatação multi-item via all() com suporte a Autoatendimento L1!
const prepItems = $('07_Prepare_AI_Deal_Input').all();
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const agentItem = items[i].json;
  const prevData = prepItems[i]?.json || {};

  const rawOutput = agentItem.output || agentItem.text || '';
  let cleanMessage = String(rawOutput).trim();
  let structuredData = null;

  const match = cleanMessage.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/i);
  if (match) {
    try {
      structuredData = JSON.parse(match[1]);
      cleanMessage = cleanMessage.replace(match[0], '').trim();
    } catch (e) {}
  }

  const isResolvedL1 = Boolean(structuredData && (structuredData.action === 'RESOLVED_L1' || structuredData.resolvido_l1 === true || structuredData.testes_l1?.resultado === 'SUCESSO'));
  const isComplete = Boolean(structuredData && (structuredData.action === 'COMPLETE' || isResolvedL1 || structuredData.status_triagem === 'concluido'));

  results.push({
    json: {
      deal_id: prevData.deal_id,
      chat_id: prevData.chat_id,
      dialog_id: prevData.dialog_id,
      requester_user_id: prevData.requester_user_id,
      requester_name: prevData.requester_name || 'Colaborador',
      message_id: prevData.message_id,
      reply_text: cleanMessage,
      structured_data: structuredData,
      is_complete: isComplete,
      is_resolved_l1: isResolvedL1,
      collected_data_json: prevData.collected_data_json || {}
    }
  });
}

return results;

// Cursor SOMENTE após envio com sucesso no Bitrix
// Correção de indexação: consome branch FALSE (outputIndex 1) de 09_If_Triage_Complete
const askInputs = $('09_If_Triage_Complete').all(1);
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const bitrixRes = items[i].json;
  const itemIdx = items[i].pairedItem?.item ?? i;
  const askData = askInputs[itemIdx]?.json || askInputs[i]?.json || {};

  if (bitrixRes.result && askData.deal_id) {
    results.push({
      json: {
        deal_id: askData.deal_id,
        message_id: askData.message_id,
        sent_bitrix_msg_id: bitrixRes.result
      }
    });
  }
}

return results;

// MOTOR DETERMINÍSTICO B01 DE PRIORIDADE & SUPORTE A AUTOATENDIMENTO L1
// Sprint 1: Detecção de Frustração e Cliente em Loja
// Sprint 2: Queda Geral por Loja (Incident Clustering P1)
const items = $input.all();
const results = [];

const IMPACT_MAP = {
  'ENTIRE_COMPANY': { id: 1180, label: 'Empresa Inteira (Todas as Lojas)' },
  'ENTIRE_STORE': { id: 1182, label: 'Loja Inteira' },
  'ENTIRE_DEPARTMENT': { id: 1184, label: 'Departamento Inteiro' },
  'MULTIPLE_USERS': { id: 1186, label: 'Múltiplos Usuários' },
  'SINGLE_USER': { id: 1188, label: 'Usuário Individual' },
  'NO_IMPACT': { id: 1190, label: 'Sem Impacto Operacional' }
};

const URGENCY_MAP = {
  'OPERATION_HALTED': { id: 1192, label: 'Operação Parada (Crítico)' },
  'SEVERELY_DEGRADED': { id: 1194, label: 'Severamente Degradada' },
  'WORKAROUND_AVAILABLE': { id: 1196, label: 'Contorno Disponível' },
  'PLANNED_REQUEST': { id: 1198, label: 'Solicitação Planejada' },
  'INQUIRY': { id: 1200, label: 'Dúvida / Informação' }
};

for (const item of items) {
  const data = item.json.structured_data || {};
  const facts = data.facts || {};
  const isResolvedL1 = Boolean(item.json.is_resolved_l1 || data.resolvido_l1 || data.action === 'RESOLVED_L1');

  // Recupera dados de sessão do Postgres (clustering de queda de loja)
  const sessionData = item.json.collected_data_json || {};
  const isStoreOutage = Boolean(sessionData.is_store_outage || data.is_store_outage);
  const storeName = sessionData.store_name || data.store_name || '';
  const outageCount = Number(sessionData.outage_count || data.outage_count || 1);

  // Detecção de Contexto Crítico / Cliente em Loja
  const contextoCritico = data.contexto_critico || {};
  const isClienteEmLoja = Boolean(contextoCritico.cliente_em_loja);
  const isFrustracaoAlta = Boolean(contextoCritico.frustracao_alta);
  const motivoCritico = String(contextoCritico.motivo || '').trim();

  let rawImpact = (facts.impacto?.value || data.impacto || 'SINGLE_USER').toUpperCase();
  let rawUrgency = (facts.urgencia?.value || data.urgencia || 'NORMAL').toUpperCase();

  // Força Urgência OPERATION_HALTED se tiver cliente em loja ou queda de loja
  if (isStoreOutage) {
    rawImpact = 'ENTIRE_STORE';
    rawUrgency = 'OPERATION_HALTED';
  } else if (isClienteEmLoja) {
    rawUrgency = 'OPERATION_HALTED';
  }

  const impactObj = IMPACT_MAP[rawImpact] || IMPACT_MAP['SINGLE_USER'];
  const urgencyObj = URGENCY_MAP[rawUrgency] || URGENCY_MAP['PLANNED_REQUEST'];

  let priorityId = 1206; // P3_MEDIUM Default
  let priorityCode = 'P3_MEDIUM';
  let priorityLabel = 'P3 - Médio';

  if (isStoreOutage) {
    priorityId = 1202;
    priorityCode = 'P1_CRITICAL';
    priorityLabel = 'P1 - Crítico (Queda Geral de Loja)';
  } else if (isResolvedL1) {
    priorityId = 1208;
    priorityCode = 'P4_LOW';
    priorityLabel = 'P4 - Resolvido L1';
  } else if (rawImpact === 'ENTIRE_COMPANY') {
    if (rawUrgency === 'OPERATION_HALTED' || rawUrgency === 'SEVERELY_DEGRADED') {
      priorityId = 1202; priorityCode = 'P1_CRITICAL'; priorityLabel = 'P1 - Crítico';
    } else if (rawUrgency === 'WORKAROUND_AVAILABLE') {
      priorityId = 1204; priorityCode = 'P2_HIGH'; priorityLabel = 'P2 - Alto';
    } else if (rawUrgency === 'PLANNED_REQUEST') {
      priorityId = 1206; priorityCode = 'P3_MEDIUM'; priorityLabel = 'P3 - Médio';
    } else {
      priorityId = 1208; priorityCode = 'P4_LOW'; priorityLabel = 'P4 - Baixo';
    }
  } else if (rawImpact === 'ENTIRE_STORE') {
    if (rawUrgency === 'OPERATION_HALTED') {
      priorityId = 1202; priorityCode = 'P1_CRITICAL'; priorityLabel = 'P1 - Crítico';
    } else if (rawUrgency === 'SEVERELY_DEGRADED' || rawUrgency === 'WORKAROUND_AVAILABLE') {
      priorityId = 1204; priorityCode = 'P2_HIGH'; priorityLabel = 'P2 - Alto';
    } else if (rawUrgency === 'PLANNED_REQUEST') {
      priorityId = 1206; priorityCode = 'P3_MEDIUM'; priorityLabel = 'P3 - Médio';
    } else {
      priorityId = 1208; priorityCode = 'P4_LOW'; priorityLabel = 'P4 - Baixo';
    }
  } else if (rawImpact === 'ENTIRE_DEPARTMENT') {
    if (rawUrgency === 'OPERATION_HALTED' || rawUrgency === 'SEVERELY_DEGRADED') {
      priorityId = 1204; priorityCode = 'P2_HIGH'; priorityLabel = 'P2 - Alto';
    } else if (rawUrgency === 'WORKAROUND_AVAILABLE' || rawUrgency === 'PLANNED_REQUEST') {
      priorityId = 1206; priorityCode = 'P3_MEDIUM'; priorityLabel = 'P3 - Médio';
    } else {
      priorityId = 1208; priorityCode = 'P4_LOW'; priorityLabel = 'P4 - Baixo';
    }
  } else if (rawImpact === 'MULTIPLE_USERS') {
    if (rawUrgency === 'OPERATION_HALTED') {
      priorityId = 1204; priorityCode = 'P2_HIGH'; priorityLabel = 'P2 - Alto';
    } else if (rawUrgency === 'SEVERELY_DEGRADED' || rawUrgency === 'WORKAROUND_AVAILABLE') {
      priorityId = 1206; priorityCode = 'P3_MEDIUM'; priorityLabel = 'P3 - Médio';
    } else {
      priorityId = 1208; priorityCode = 'P4_LOW'; priorityLabel = 'P4 - Baixo';
    }
  } else if (rawImpact === 'SINGLE_USER') {
    if (rawUrgency === 'OPERATION_HALTED' || rawUrgency === 'SEVERELY_DEGRADED') {
      if (isClienteEmLoja) {
        priorityId = 1204; priorityCode = 'P2_HIGH'; priorityLabel = 'P2 - Alto (Cliente em Loja)';
      } else {
        priorityId = 1206; priorityCode = 'P3_MEDIUM'; priorityLabel = 'P3 - Médio';
      }
    } else {
      priorityId = 1208; priorityCode = 'P4_LOW'; priorityLabel = 'P4 - Baixo';
    }
  } else {
    priorityId = 1208; priorityCode = 'P4_LOW'; priorityLabel = 'P4 - Baixo';
  }

  const shortSubject = data.assunto_curto || 'Atendimento de TI';
  const tema = data.tema || 'GERAL';
  const resumo = data.resumo_problema || 'Triagem realizada pelo assistente de IA.';
  const lowerContext = (tema + ' ' + shortSubject + ' ' + resumo).toLowerCase();
  const isPurchaseSemantic = (
    tema === 'COMPRA' ||
    lowerContext.includes('compra') ||
    lowerContext.includes('comprar') ||
    lowerContext.includes('memoria ram') ||
    lowerContext.includes('memória ram') ||
    lowerContext.includes('hardware') ||
    lowerContext.includes('aquisição') ||
    lowerContext.includes('aquisicao')
  );
  const isPurchase = Boolean(item.json.is_purchase || isPurchaseSemantic);

  // Formatação do Título com Selo Crítico
  let prefixoCritico = '';
  if (isStoreOutage) {
    prefixoCritico = `[🚨 QUEDA GERAL ${storeName.toUpperCase()}] `;
  } else if (isClienteEmLoja) {
    prefixoCritico = '[🚨 CLIENTE EM LOJA] ';
  } else if (isFrustracaoAlta) {
    prefixoCritico = '[⚠️ PRIORITÁRIO] ';
  }

  const formattedTitle = isResolvedL1 
    ? `[RESOLVIDO-L1] - ${shortSubject} (${item.json.requester_name || "Colaborador"})` 
    : `${prefixoCritico}[TI-${tema}] - ${shortSubject} (${item.json.requester_name || "Colaborador"})`;
  const targetStageId = isResolvedL1 ? 'C160:WON' : (isPurchase ? 'C160:UC_JIOBG8' : 'C160:NEW');

  results.push({
    json: {
      deal_id: item.json.deal_id,
      chat_id: item.json.chat_id,
      dialog_id: item.json.dialog_id,
      message_id: item.json.message_id,
      impact_id: impactObj.id,
      impact_label: impactObj.label,
      urgency_id: urgencyObj.id,
      urgency_label: urgencyObj.label,
      priority_id: priorityId,
      priority_code: priorityCode,
      priority_label: priorityLabel,
      target_stage_id: targetStageId,
      is_resolved_l1: isResolvedL1,
      is_purchase: isPurchase,
      is_store_outage: isStoreOutage,
      store_name: storeName,
      outage_count: outageCount,
      is_cliente_em_loja: isClienteEmLoja,
      is_frustracao_alta: isFrustracaoAlta,
      motivo_critico: motivoCritico,
      tema: tema,
      short_subject: shortSubject,
      formatted_title: formattedTitle,
      resumo: resumo,
      requester_name: item.json.requester_name || 'Colaborador',
      store_name: storeName || (item.json.collected_data_json?.store_name) || 'Geral',
      next_owner_id: 1148,
      wait_reason_id: 1162
    }
  });
}

return results;

// Combina dados do B01 com a descrição existente do Deal via all()
const b01Items = $('11_B01_Priority_And_Payload').all();
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const b01 = b01Items[i]?.json || {};
  const deal = items[i].json.result || items[i].json || {};

  // Detecção de compra enriquecida com campos do Bitrix
  const ufCategory = String(deal.UF_CRM_1763388156 || '');
  const dealTitle = String(deal.TITLE || '').toLowerCase();
  let dealDesc = '';
  if (Array.isArray(deal.UF_CRM_1729774515200)) {
    dealDesc = deal.UF_CRM_1729774515200.join(' ').toLowerCase();
  } else if (deal.UF_CRM_1729774515200) {
    dealDesc = String(deal.UF_CRM_1729774515200).toLowerCase();
  }

  const isPurchaseDeal = (
    ufCategory === '876' ||
    dealTitle.includes('compra') ||
    dealTitle.includes('comprar') ||
    dealDesc.includes('compra') ||
    dealDesc.includes('comprar') ||
    dealDesc.includes('memoria ram') ||
    dealDesc.includes('memória ram')
  );

  const finalIsPurchase = Boolean(b01.is_purchase || isPurchaseDeal);
  const finalTargetStage = b01.is_resolved_l1 ? 'C160:WON' : (finalIsPurchase ? 'C160:UC_JIOBG8' : b01.target_stage_id);

  // Resumo do robô formatado (sem emojis de 4-bytes para evitar incompatibilidade no MySQL do Bitrix)
  const milestoneSummary = b01.is_resolved_l1
    ? `[AUTOATENDIMENTO L1 RESOLVIDO]\n---------------------------------------------\nTema: ${b01.tema}\nPrioridade: ${b01.priority_label}\n\nResumo:\n${b01.resumo}\n\n(Chamado concluído automaticamente como Ganho)`
    : `[TRIAGEM IA CONCLUÍDA]\n---------------------------------------------\nTema: ${b01.tema}\nImpacto: ${b01.impact_label}\nUrgência: ${b01.urgency_label}\nPrioridade B01: ${b01.priority_label} (${b01.priority_code})\nEtapa: ${finalIsPurchase ? 'Aguardando autorização (Compra)' : 'Novo Chamado'}\n\nResumo:\n${b01.resumo}\n\n(Histórico detalhado da conversa mantido no Chat do Card)`;

  // Recupera descrição existente no campo UF_CRM_1729774515200 (Descrição)
  let existingDescList = deal.UF_CRM_1729774515200;
  let existingDescArray = [];
  if (Array.isArray(existingDescList)) {
    existingDescArray = existingDescList.map(x => String(x || '').trim()).filter(Boolean);
  } else if (existingDescList) {
    existingDescArray = [String(existingDescList).trim()];
  }

  // Preserva a descrição do usuário e adiciona o resumo do robô como complemento
  const finalDescArray = [...existingDescArray, milestoneSummary];

  // Recupera campo COMMENTS (Observação)
  const existingComments = String(deal.COMMENTS || '').trim();
  const finalComments = existingComments
    ? `${existingComments}\n\n---------------------------------------------\n${milestoneSummary}`
    : milestoneSummary;

  results.push({
    json: {
      ...b01,
      is_purchase: finalIsPurchase,
      target_stage_id: finalTargetStage,
      final_desc_array: finalDescArray,
      final_comments: finalComments
    }
  });
}

return results;

